namespace sv_94c64a7207de40a8b5d33fa222ad5cae.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@namespace sv_94c64a7207de40a8b5d33fa222ad5cae.Components.Application

<nav aria-label="Application steps" class="mb-4">
    <div class="d-flex justify-content-between position-relative step-indicator">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var step = i;
            var isCompleted = step < CurrentStep;
            var isCurrent = step == CurrentStep;
            var isFuture = step > CurrentStep;

            <div class="text-center step-item @(isCurrent ? "active" : "") @(isCompleted ? "completed" : "") @(isFuture ? "dimmed" : "")">
                <button class="btn rounded-circle step-circle @(isCurrent ? "btn-primary" : isCompleted ? "btn-success" : "btn-outline-secondary")"
                        disabled="@isFuture"
                        @onclick="() => OnStepClicked.InvokeAsync(step)"
                        aria-label="@(isCompleted ? $"Edit {StepNames[step]}" : StepNames[step])">
                    @if (isCompleted)
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        <span>@(step + 1)</span>
                    }
                </button>
                <div class="small mt-1 @(isFuture ? "text-muted" : "")">@StepNames[step]</div>
            </div>
        }
    </div>
</nav>

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnStepClicked { get; set; }
}

@namespace sv_94c64a7207de40a8b5d33fa222ad5cae.Components.Application

<h4 class="mb-3">Personal Information</h4>

<div class="mb-3">
    <label class="form-label">Full Name <span class="text-danger">*</span></label>
    <input class="form-control @(errors.ContainsKey("name") ? "is-invalid" : "")"
           @bind="fullName" @bind:event="oninput" placeholder="John Doe" />
    @if (errors.ContainsKey("name"))
    {
        <div class="invalid-feedback">@errors["name"]</div>
    }
</div>

<div class="mb-3">
    <label class="form-label">Email <span class="text-danger">*</span></label>
    <input type="email" class="form-control @(errors.ContainsKey("email") ? "is-invalid" : "")"
           @bind="email" @bind:event="oninput" placeholder="john@example.com" />
    @if (errors.ContainsKey("email"))
    {
        <div class="invalid-feedback">@errors["email"]</div>
    }
</div>

<div class="mb-3">
    <label class="form-label">Phone <span class="text-danger">*</span></label>
    <input type="tel" class="form-control @(errors.ContainsKey("phone") ? "is-invalid" : "")"
           @bind="phone" @bind:event="oninput" placeholder="(555) 123-4567" />
    @if (errors.ContainsKey("phone"))
    {
        <div class="invalid-feedback">@errors["phone"]</div>
    }
</div>

<div class="mb-3">
    <label class="form-label">Address <span class="text-danger">*</span></label>
    <textarea class="form-control @(errors.ContainsKey("address") ? "is-invalid" : "")"
              @bind="address" @bind:event="oninput" rows="2" placeholder="123 Main St, City, State ZIP"></textarea>
    @if (errors.ContainsKey("address"))
    {
        <div class="invalid-feedback">@errors["address"]</div>
    }
</div>

@if (validating)
{
    <div class="text-info mb-2"><span class="spinner-border spinner-border-sm"></span> Validating email...</div>
}

<div class="d-flex justify-content-end">
    <button class="btn btn-primary" @onclick="HandleNext" disabled="@validating">Next &raquo;</button>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<PersonalInfoResult> OnNext { get; set; }
    [Parameter, EditorRequired] public Func<string, Task<bool>> ValidateEmail { get; set; } = default!;

    private string fullName = "";
    private string email = "";
    private string phone = "";
    private string address = "";
    private bool validating;
    private Dictionary<string, string> errors = new();

    protected override void OnParametersSet()
    {
        fullName = FullName;
        email = Email;
        phone = Phone;
        address = Address;
    }

    private async Task HandleNext()
    {
        errors.Clear();

        if (string.IsNullOrWhiteSpace(fullName)) errors["name"] = "Full name is required.";
        if (string.IsNullOrWhiteSpace(email)) errors["email"] = "Email is required.";
        if (string.IsNullOrWhiteSpace(phone)) errors["phone"] = "Phone is required.";
        if (string.IsNullOrWhiteSpace(address)) errors["address"] = "Address is required.";

        if (errors.Count > 0) return;

        validating = true;
        StateHasChanged();

        try
        {
            var isValid = await ValidateEmail(email);
            if (!isValid)
            {
                errors["email"] = "Email address is not valid.";
                return;
            }
        }
        finally
        {
            validating = false;
        }

        await OnNext.InvokeAsync(new PersonalInfoResult(fullName.Trim(), email.Trim(), phone.Trim(), address.Trim()));
    }

    public record PersonalInfoResult(string FullName, string Email, string Phone, string Address);
}

@namespace sv_94c64a7207de40a8b5d33fa222ad5cae.Components.Application

<div class="card mb-3">
    <div class="card-body">
        <div class="d-flex justify-content-between align-items-center mb-2">
            <h6 class="card-title mb-0">Position @(Index + 1)</h6>
            @if (CanRemove)
            {
                <button class="btn btn-sm btn-outline-danger" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
            }
        </div>

        <div class="row g-2 mb-2">
            <div class="col-md-6">
                <label class="form-label">Company <span class="text-danger">*</span></label>
                <input class="form-control" value="@Company" @oninput="e => { Company = e.Value?.ToString() ?? ""; NotifyChanged(); }" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Job Title <span class="text-danger">*</span></label>
                <input class="form-control" value="@Title" @oninput="e => { Title = e.Value?.ToString() ?? ""; NotifyChanged(); }" />
            </div>
        </div>

        <div class="row g-2 mb-2">
            <div class="col-md-4">
                <label class="form-label">Start Date <span class="text-danger">*</span></label>
                <input type="date" class="form-control" value="@StartDate?.ToString("yyyy-MM-dd")"
                       @onchange="e => { StartDate = DateTime.TryParse(e.Value?.ToString(), out var d) ? d : null; NotifyChanged(); }" />
            </div>
            <div class="col-md-4">
                <label class="form-label">End Date</label>
                <input type="date" class="form-control" value="@EndDate?.ToString("yyyy-MM-dd")" disabled="@IsCurrent"
                       @onchange="e => { EndDate = DateTime.TryParse(e.Value?.ToString(), out var d) ? d : null; NotifyChanged(); }" />
            </div>
            <div class="col-md-4 d-flex align-items-end">
                <div class="form-check mb-2">
                    <input type="checkbox" class="form-check-input" id="current-@Index" checked="@IsCurrent"
                           @onchange="e => { IsCurrent = (bool)(e.Value ?? false); if (IsCurrent) EndDate = null; NotifyChanged(); }" />
                    <label class="form-check-label" for="current-@Index">Currently working here</label>
                </div>
            </div>
        </div>

        <div class="mb-0">
            <label class="form-label">Description</label>
            <textarea class="form-control" rows="2" value="@Description"
                      @oninput="e => { Description = e.Value?.ToString() ?? ""; NotifyChanged(); }"></textarea>
        </div>
    </div>
</div>

@code {
    [Parameter] public int Index { get; set; }
    [Parameter] public string Company { get; set; } = "";
    [Parameter] public string Title { get; set; } = "";
    [Parameter] public DateTime? StartDate { get; set; }
    [Parameter] public DateTime? EndDate { get; set; }
    [Parameter] public bool IsCurrent { get; set; }
    [Parameter] public string Description { get; set; } = "";
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryData> OnChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private void NotifyChanged()
    {
        OnChanged.InvokeAsync(new WorkEntryData(Company, Title, StartDate, IsCurrent ? null : EndDate, IsCurrent, Description));
    }

    public record WorkEntryData(string Company, string Title, DateTime? StartDate, DateTime? EndDate, bool IsCurrent, string Description);
}

