@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<PersonalInfoResult> OnNext { get; set; }
    [Parameter, EditorRequired] public Func<string, Task<bool>> ValidateEmail { get; set; } = default!;

    private string fullName = "";
    private string email = "";
    private string phone = "";
    private string address = "";
    private bool validating;
    private Dictionary<string, string> errors = new();

    protected override void OnParametersSet()
    {
        fullName = FullName;
        email = Email;
        phone = Phone;
        address = Address;
    }

    private async Task HandleNext()
    {
        errors.Clear();

        if (string.IsNullOrWhiteSpace(fullName)) errors["name"] = "Full name is required.";
        if (string.IsNullOrWhiteSpace(email)) errors["email"] = "Email is required.";
        if (string.IsNullOrWhiteSpace(phone)) errors["phone"] = "Phone is required.";
        if (string.IsNullOrWhiteSpace(address)) errors["address"] = "Address is required.";

        if (errors.Count > 0) return;

        validating = true;
        StateHasChanged();

        try
        {
            var isValid = await ValidateEmail(email);
            if (!isValid)
            {
                errors["email"] = "Email address is not valid.";
                return;
            }
        }
        finally
        {
            validating = false;
        }

        await OnNext.InvokeAsync(new PersonalInfoResult(fullName.Trim(), email.Trim(), phone.Trim(), address.Trim()));
    }

    public record PersonalInfoResult(string FullName, string Email, string Phone, string Address);
}
"}

