namespace sv_94c64a7207de40a8b5d33fa222ad5cae.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@namespace sv_94c64a7207de40a8b5d33fa222ad5cae.Components.Application

<h4 class="mb-3">Work History</h4>

@for (int i = 0; i < entries.Count; i++)
{
    var index = i;
    var entry = entries[index];
    <WorkEntryForm Index="index"
                   Company="@entry.Company"
                   Title="@entry.Title"
                   StartDate="@entry.StartDate"
                   EndDate="@entry.EndDate"
                   IsCurrent="@entry.IsCurrent"
                   Description="@entry.Description"
                   CanRemove="@(entries.Count > 1)"
                   OnChanged="data => UpdateEntry(index, data)"
                   OnRemove="() => RemoveEntry(index)" />
}

@if (!string.IsNullOrEmpty(validationError))
{
    <div class="alert alert-danger">@validationError</div>
}

<button class="btn btn-outline-secondary mb-3" @onclick="AddEntry">
    <span>+</span> Add Another Position
</button>

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="() => OnBack.InvokeAsync()">&laquo; Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next &raquo;</button>
</div>

@code {
    [Parameter] public List<WorkEntryState>? InitialEntries { get; set; }
    [Parameter, EditorRequired] public EventCallback<List<WorkEntryState>> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private List<WorkEntryState> entries = new();
    private string? validationError;

    protected override void OnParametersSet()
    {
        if (entries.Count == 0)
        {
            entries = InitialEntries?.Count > 0
                ? InitialEntries.Select(e => e with { }).ToList()
                : new List<WorkEntryState> { new() };
        }
    }

    private void AddEntry() => entries.Add(new WorkEntryState());

    private void RemoveEntry(int index)
    {
        if (entries.Count > 1) entries.RemoveAt(index);
    }

    private void UpdateEntry(int index, WorkEntryForm.WorkEntryData data)
    {
        entries[index] = new WorkEntryState
        {
            Company = data.Company,
            Title = data.Title,
            StartDate = data.StartDate,
            EndDate = data.EndDate,
            IsCurrent = data.IsCurrent,
            Description = data.Description
        };
    }

    private async Task HandleNext()
    {
        validationError = null;

        foreach (var e in entries)
        {
            if (string.IsNullOrWhiteSpace(e.Company) || string.IsNullOrWhiteSpace(e.Title) || e.StartDate == null)
            {
                validationError = "Each position requires a company name, job title, and start date.";
                return;
            }
        }

        await OnNext.InvokeAsync(entries);
    }

    public class WorkEntryState
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime? StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }
}

@namespace sv_94c64a7207de40a8b5d33fa222ad5cae.Components.Application

<h4 class="mb-3">References</h4>
<p class="text-muted">Please provide 2–3 professional references.</p>

@for (int i = 0; i < references.Count; i++)
{
    var index = i;
    var r = references[index];
    <ReferenceForm Index="index"
                   Name="@r.Name"
                   Relationship="@r.Relationship"
                   Email="@r.Email"
                   Phone="@r.Phone"
                   CanRemove="@(references.Count > 2)"
                   OnChanged="data => UpdateReference(index, data)"
                   OnRemove="() => RemoveReference(index)" />
}

@if (!string.IsNullOrEmpty(validationError))
{
    <div class="alert alert-danger">@validationError</div>
}

@if (references.Count < 3)
{
    <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">
        <span>+</span> Add Reference
    </button>
}

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="() => OnBack.InvokeAsync()">&laquo; Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next &raquo;</button>
</div>

@code {
    [Parameter] public List<ReferenceState>? InitialReferences { get; set; }
    [Parameter, EditorRequired] public EventCallback<List<ReferenceState>> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private List<ReferenceState> references = new();
    private string? validationError;

    protected override void OnParametersSet()
    {
        if (references.Count == 0)
        {
            references = InitialReferences?.Count >= 2
                ? InitialReferences.Select(r => r with { }).ToList()
                : new List<ReferenceState> { new(), new() };
        }
    }

    private void AddReference()
    {
        if (references.Count < 3) references.Add(new ReferenceState());
    }

    private void RemoveReference(int index)
    {
        if (references.Count > 2) references.RemoveAt(index);
    }

    private void UpdateReference(int index, ReferenceForm.ReferenceData data)
    {
        references[index] = new ReferenceState
        {
            Name = data.Name,
            Relationship = data.Relationship,
            Email = data.Email,
            Phone = data.Phone
        };
    }

    private async Task HandleNext()
    {
        validationError = null;

        foreach (var r in references)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
                || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                validationError = "All reference fields are required.";
                return;
            }
        }

        await OnNext.InvokeAsync(references);
    }

    public record ReferenceState
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

@namespace sv_94c64a7207de40a8b5d33fa222ad5cae.Components.Application

<h4 class="mb-3">Cover Letter</h4>

<div class="mb-2">
    <textarea class="form-control" rows="12" @bind="coverLetter" @bind:event="oninput"
              placeholder="Tell us why you're a great fit for this position..." maxlength="@MaxLength"></textarea>
</div>
<div class="text-muted text-end mb-3">
    @coverLetter.Length / @MaxLength characters
</div>

@if (!string.IsNullOrEmpty(validationError))
{
    <div class="alert alert-danger">@validationError</div>
}

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="() => OnBack.InvokeAsync()">&laquo; Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next &raquo;</button>
</div>

@code {
    private const int MaxLength = 2000;

    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<string> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string coverLetter = "";
    private string? validationError;

    protected override void OnParametersSet()
    {
        coverLetter = CoverLetter;
    }

    private async Task HandleNext()
    {
        validationError = null;

        if (string.IsNullOrWhiteSpace(coverLetter))
        {
            validationError = "A cover letter is required.";
            return;
        }

        await OnNext.InvokeAsync(coverLetter.Trim());
    }
}

@namespace sv_94c64a7207de40a8b5d33fa222ad5cae.Components.Application
@using sv_94c64a7207de40a8b5d33fa222ad5cae.Models

<h4 class="mb-3">Review &amp; Submit</h4>

@if (Submitted)
{
    <div class="alert alert-success text-center py-4">
        <h5>&#10003; Application Submitted Successfully!</h5>
        <p class="mb-0">Your application ID is <strong>#@ApplicationId</strong>. We'll be in touch soon.</p>
    </div>
}
else
{
    @* Personal Info *@
