@namespace sv_94c64a7207de40a8b5d33fa222ad5cae.Components.Application

<h4 class="mb-3">References</h4>
<p class="text-muted">Please provide 2–3 professional references.</p>

@for (int i = 0; i < references.Count; i++)
{
    var index = i;
    var r = references[index];
    <ReferenceForm Index="index"
                   Name="@r.Name"
                   Relationship="@r.Relationship"
                   Email="@r.Email"
                   Phone="@r.Phone"
                   CanRemove="@(references.Count > 2)"
                   OnChanged="data => UpdateReference(index, data)"
                   OnRemove="() => RemoveReference(index)" />
}

@if (!string.IsNullOrEmpty(validationError))
{
    <div class="alert alert-danger">@validationError</div>
}

@if (references.Count < 3)
{
    <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">
        <span>+</span> Add Reference
    </button>
}

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="() => OnBack.InvokeAsync()">&laquo; Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next &raquo;</button>
</div>

@code {
    [Parameter] public List<ReferenceState>? InitialReferences { get; set; }
    [Parameter, EditorRequired] public EventCallback<List<ReferenceState>> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private List<ReferenceState> references = new();
    private string? validationError;

    protected override void OnParametersSet()
    {
        if (references.Count == 0)
        {
            references = InitialReferences?.Count >= 2
                ? InitialReferences.Select(r => r with { }).ToList()
                : new List<ReferenceState> { new(), new() };
        }
    }

    private void AddReference()
    {
        if (references.Count < 3) references.Add(new ReferenceState());
    }

    private void RemoveReference(int index)
    {
        if (references.Count > 2) references.RemoveAt(index);
    }

    private void UpdateReference(int index, ReferenceForm.ReferenceData data)
    {
        references[index] = new ReferenceState
        {
            Name = data.Name,
            Relationship = data.Relationship,
            Email = data.Email,
            Phone = data.Phone
        };
    }

    private async Task HandleNext()
    {
        validationError = null;

        foreach (var r in references)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
                || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                validationError = "All reference fields are required.";
                return;
            }
        }

        await OnNext.InvokeAsync(references);
    }

    public record ReferenceState
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

