+        <button class="btn btn-success btn-lg" @onclick="HandleSubmit" disabled="@submitting">
+            @if (submitting)
+            {
+                <span class="spinner-border spinner-border-sm"></span> @:Submitting...
+            }
+            else
+            {
+                @:Submit Application
+            }
+        </button>
+    </div>
