@page "/apply"
@rendermode InteractiveServer
@using sv_94c64a7207de40a8b5d33fa222ad5cae.Components.Application
@using sv_94c64a7207de40a8b5d33fa222ad5cae.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="text-center mb-4">Job Application</h2>

    <StepIndicator CurrentStep="currentStep" OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep FullName="@personalInfo.FullName"
                              Email="@personalInfo.Email"
                              Phone="@personalInfo.Phone"
                              Address="@personalInfo.Address"
                              ValidateEmail="ApplicationService.ValidateEmailAsync"
                              OnNext="HandlePersonalInfoNext" />
            break;

        case 1:
            <WorkHistoryStep InitialEntries="workEntries"
                             OnNext="HandleWorkHistoryNext"
                             OnBack="() => currentStep--" />
            break;

        case 2:
            <ReferencesStep InitialReferences="references"
                            OnNext="HandleReferencesNext"
                            OnBack="() => currentStep--" />
            break;

        case 3:
            <CoverLetterStep CoverLetter="@coverLetter"
                             OnNext="HandleCoverLetterNext"
                             OnBack="() => currentStep--" />
            break;

        case 4:
            <ReviewStep Personal="@personalInfo"
                        WorkEntries="workEntries"
                        References="references"
                        CoverLetter="@coverLetter"
                        Submitted="submitted"
                        ApplicationId="applicationId"
                        OnEditStep="GoToStep"
                        OnBack="() => currentStep--"
                        OnSubmit="SubmitApplication" />
            break;
    }
</div>

@code {
    private int currentStep;
    private PersonalInfo personalInfo = new("", "", "", "");
    private List<WorkHistoryStep.WorkEntryState> workEntries = new();
    private List<ReferencesStep.ReferenceState> references = new();
    private string coverLetter = "";
    private bool submitted;
    private int applicationId;

    private void GoToStep(int step)
    {
        if (step < currentStep)
            currentStep = step;
    }

    private void HandlePersonalInfoNext(PersonalInfoStep.PersonalInfoResult result)
    {
        personalInfo = new PersonalInfo(result.FullName, result.Email, result.Phone, result.Address);
        currentStep = 1;
    }

    private void HandleWorkHistoryNext(List<WorkHistoryStep.WorkEntryState> entries)
    {
        workEntries = entries;
        currentStep = 2;
    }

    private void HandleReferencesNext(List<ReferencesStep.ReferenceState> refs)
    {
        references = refs;
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string text)
    {
        coverLetter = text;
        currentStep = 4;
    }

    private async Task<int> SubmitApplication()
    {
        var workHistory = new WorkHistory(
            workEntries.Select(e => new WorkEntry(
                e.Company, e.Title, e.StartDate ?? DateTime.Today, e.EndDate, e.Description
            )).ToList()
        );

        var refs = references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
        var application = new JobApplication(personalInfo, workHistory, refs, coverLetter);

        applicationId = await ApplicationService.SubmitApplicationAsync(application);
        submitted = true;
        StateHasChanged();
        return applicationId;
    }
}

.step-indicator {
    counter-reset: step;
}

.step-item {
    flex: 1;
    position: relative;
}

.step-circle {
    width: 40px;
    height: 40px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
}

.step-item.dimmed {
    opacity: 0.5;
}

.step-item + .step-item::before {
    content: "";
    position: absolute;
    top: 20px;
    left: calc(-50% + 20px);
    right: calc(50% + 20px);
    height: 2px;
    background-color: #dee2e6;
}

.step-item.active + .step-item::before,
.step-item.completed + .step-item::before {
    background-color: #0d6efd;
}

.step-item.completed + .step-item.completed::before {
    background-color: #198754;
}

