    flex: 1;
    position: relative;
}

.step-circle {
    width: 40px;
    height: 40px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
}

.step-item.dimmed {
    opacity: 0.5;
}

.step-item + .step-item::before {
    content: "";
    position: absolute;
    top: 20px;
    left: calc(-50% + 20px);
    right: calc(50% + 20px);
    height: 2px;
    background-color: #dee2e6;
}

.step-item.active + .step-item::before,
.step-item.completed + .step-item::before {
    background-color: #0d6efd;
}

.step-item.completed + .step-item.completed::before {
    background-color: #198754;
}

